actions.script:
const drives = ec.service.sync().name('org.moqui.resource.FileServices.get#UserDrives').parameter('includeUsage', false).call()
const recent = ec.message.hasError() ? null : ec.service.sync().name('ironstone.commons.DriveServices.find#FileRows').parameters({view: 'recent', limit: 12}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {personalDriveId: drives.personalDriveId,
    driveList: Array.from(drives.driveList || []).map((drive) => ({driveId: drive.driveId, driveName: drive.isPersonal ? ec.l10n.localize('My files') : drive.driveName,
        isPersonal: drive.isPersonal, isRecords: drive.driveKindEnumId === 'RdkRecords'})), recentList: recent.fileList || []})
